CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY,email TEXT NOT NULL UNIQUE,pw TEXT NOT NULL,role TEXT NOT NULL DEFAULT 'user' CHECK(role IN('user','admin')),created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sessions(token TEXT PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS profiles(user_id INTEGER PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,edu INTEGER NOT NULL CHECK(edu BETWEEN 0 AND 5),stream TEXT NOT NULL DEFAULT '',studying TEXT NOT NULL DEFAULT 'No',skills TEXT NOT NULL DEFAULT '',interests TEXT NOT NULL DEFAULT '[]',sector TEXT NOT NULL DEFAULT 'Any',location TEXT NOT NULL DEFAULT '',intent TEXT NOT NULL DEFAULT 'job' CHECK(intent IN('job','exam','edu','voc')),experience TEXT NOT NULL DEFAULT '',hpd REAL NOT NULL CHECK(hpd>0 AND hpd<=12),hpw REAL NOT NULL CHECK(hpw>0 AND hpw<=70),rest TEXT NOT NULL DEFAULT '[0]',start TEXT NOT NULL DEFAULT '18:00');
CREATE TABLE IF NOT EXISTS skills(id INTEGER PRIMARY KEY,name TEXT NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS user_skills(user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,skill_id INTEGER NOT NULL REFERENCES skills(id) ON DELETE CASCADE,PRIMARY KEY(user_id,skill_id));
CREATE TABLE IF NOT EXISTS careers(id TEXT PRIMARY KEY,name TEXT NOT NULL,domain TEXT NOT NULL,sector TEXT NOT NULL CHECK(sector IN('Government','Private','Education pathway')),category TEXT NOT NULL,min_edu INTEGER NOT NULL CHECK(min_edu BETWEEN 0 AND 5),interests TEXT NOT NULL DEFAULT '[]',description TEXT NOT NULL,eligibility TEXT NOT NULL,selection TEXT NOT NULL,months INTEGER NOT NULL CHECK(months>0),phases TEXT NOT NULL,source_url TEXT,verified_on TEXT,status TEXT NOT NULL DEFAULT 'sample-unverified' CHECK(status IN('sample-unverified','verified','needs-source')));
CREATE TABLE IF NOT EXISTS resources(id INTEGER PRIMARY KEY,career_id TEXT NOT NULL REFERENCES careers(id) ON DELETE CASCADE,title TEXT NOT NULL,url TEXT NOT NULL,cost TEXT NOT NULL DEFAULT 'unknown' CHECK(cost IN('free','paid','unknown')),kind TEXT);
CREATE TABLE IF NOT EXISTS goals(id INTEGER PRIMARY KEY,user_id INTEGER NOT NULL UNIQUE REFERENCES users(id) ON DELETE CASCADE,career_id TEXT NOT NULL REFERENCES careers(id),target TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS tasks(id INTEGER PRIMARY KEY,goal_id INTEGER NOT NULL REFERENCES goals(id) ON DELETE CASCADE,ord INTEGER NOT NULL,title TEXT NOT NULL,topic TEXT NOT NULL,phase TEXT NOT NULL,hours REAL NOT NULL CHECK(hours>0),date TEXT NOT NULL,done INTEGER NOT NULL DEFAULT 0,spent REAL NOT NULL DEFAULT 0,note TEXT NOT NULL DEFAULT '',completed_at TEXT,UNIQUE(goal_id,ord));
CREATE TABLE IF NOT EXISTS task_deps(task_id INTEGER NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,depends_on INTEGER NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,PRIMARY KEY(task_id,depends_on));
CREATE TABLE IF NOT EXISTS study_log(id INTEGER PRIMARY KEY,task_id INTEGER NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,hours REAL NOT NULL,logged_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS leaves(id TEXT PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,from_date TEXT NOT NULL,to_date TEXT NOT NULL,ts TEXT,te TEXT,reason TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL,UNIQUE(user_id,from_date,to_date,ts,te));
CREATE TABLE IF NOT EXISTS revisions(id INTEGER PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,at TEXT NOT NULL,reason TEXT NOT NULL,moved INTEGER NOT NULL DEFAULT 0,old_end TEXT,new_end TEXT,detail TEXT);
CREATE TABLE IF NOT EXISTS notifications(id INTEGER PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,at TEXT NOT NULL,text TEXT NOT NULL,read INTEGER NOT NULL DEFAULT 0);
CREATE INDEX IF NOT EXISTS ix_tasks_goal ON tasks(goal_id,ord);CREATE INDEX IF NOT EXISTS ix_tasks_date ON tasks(date);CREATE INDEX IF NOT EXISTS ix_leaves_user ON leaves(user_id);CREATE INDEX IF NOT EXISTS ix_careers_dom ON careers(domain,sector,category);CREATE INDEX IF NOT EXISTS ix_rev_user ON revisions(user_id);CREATE INDEX IF NOT EXISTS ix_notif_user ON notifications(user_id,read);CREATE INDEX IF NOT EXISTS ix_sess_user ON sessions(user_id);
